// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 blockNumber) public {
        vm.assume(value != 10 ether);
        vm.assume(blockNumber != 0);
        vm.roll(blockNumber);
        vm.warp(blockNumber);
        vm.deal(address(this), value);
        (bool success,) = address(c).call{value: value}("");
        assertTrue(!success, "Call should revert for value != 10 ether");
    }
}
